1	import React, { useState } from 'react';
2	import { createRoot } from 'react-dom/client';
3	import { features } from './router/routes';
4	
5	// Minimal base shell. Features register additively via the manifest router (router/routes.ts); the
6	// shell renders a nav link per feature and the active feature's page. Navigation is via nav-* clicks
7	// (no URL router needed for the specs). Every observable element carries a stable data-testid.
8	function App() {
9	  const [active, setActive] = useState<string | null>(null);
